SELECT 'Advanced Neo4j Graph Expert', 'Neo4j graph database expert that delegates analytical / multi-hop Cypher questions to the planner-based advanced Neo4j agent (label/schema discovery, plan, monitor, synthesis). Read-only; database-agnostic.', 'database', NULL, NULL, NULL, '{"model": "deepseek-chat", "temperature": 0.7, "max_tokens": 4096, "reasoning_effort": "low", "modalities": null, "system_prompt": "you are an expert for querying Neo4j graph databases with the planner-based advanced agent. For any question about the graph, call the neo4j_agent_advanced_tool — it discovers the schema at runtime, plans multi-hop Cypher queries, monitors progress, and synthesizes the final answer. The tool works against any connected graph (labels, relationship types and properties are discovered from the live schema, so no hardcoding). The tool is read-only — DML is rejected by design. Always base your answer on the tool''s result.", "tools": [], "native_tools": ["think_tool", "reasoning_chain", "write_todos", "read_todos", "memory_store", "memory_recall", "web_search", "web_fetch", "tavily_search", "rename_file", "move_file", "mkdir", "bash", "skill", "save_document", "sqlite_execute", "sqlite_load_csv", "python_execute", "save_analysis_result", "graphindex_search", "graphindex_load", "doc_index_list", "neo4j_agent_advanced_tool"], "cli_tools": [], "custom_tools": [], "use_deepagents": false, "use_phase9_graphindex": false, "enable_compiled_subagents": true, "use_local_sandbox": false, "middleware": [], "subagents": [], "backend": {"type": "state", "config": {}, "mappings": null}, "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}, "skills": [], "plugins": [], "skill_router_model": null, "disable_memory_middleware": false, "interrupt_before": null, "interrupt_after": null, "export_format": "standalone", "include_chat_ui": true, "include_docker": false, "tool_params": {"sql_agent_tool": {"database": "chinook"}, "neo4j_agent_advanced_tool": {"database": "neo4j"}}}', '[]', '[]', '{"type": "state", "config": {}, "mappings": null}', '{"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}', '{}', 0, NULL, '1', TRUE, FALSE, '2026-08-25 12:24:42.007932+00:00', '2026-08-25 13:21:06.861218+00:00', 0
