SELECT 'Advanced SQL Expert', 'SQL database expert that delegates analytical / multi-hop questions to the planner-based advanced SQL agent (schema discovery, action plan, monitor, synthesis). Read-only.', 'database', NULL, NULL, NULL, '{"model": "deepseek-chat", "temperature": 0.7, "max_tokens": 4096, "reasoning_effort": "low", "modalities": null, "system_prompt": "you are an expert for querying SQL databases with the planner-based advanced agent. For any question about a SQL database, call the advanced_sql_agent_tool — it handles schema discovery, plans multi-step queries, and synthesizes the final answer. For simple questions it returns one query; for complex / multi-hop questions it decomposes the work into a plan and runs each step with monitoring. The tool is read-only — DML is rejected by design. Always base your answer on the tool''s result.", "tools": [], "native_tools": ["think_tool", "reasoning_chain", "write_todos", "read_todos", "memory_store", "memory_recall", "web_search", "web_fetch", "tavily_search", "rename_file", "move_file", "mkdir", "bash", "skill", "save_document", "sqlite_execute", "sqlite_load_csv", "python_execute", "save_analysis_result", "advanced_sql_agent_tool"], "cli_tools": [], "custom_tools": [], "use_deepagents": false, "use_phase9_graphindex": false, "enable_compiled_subagents": true, "use_local_sandbox": false, "middleware": [], "subagents": [], "backend": {"type": "state", "config": {}, "mappings": null}, "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}, "skills": [], "plugins": [], "skill_router_model": null, "disable_memory_middleware": false, "interrupt_before": null, "interrupt_after": null, "export_format": "standalone", "include_chat_ui": true, "include_docker": false, "tool_params": {"advanced_sql_agent_tool": {"database": "chinook"}, "pg_get_agent": {}}}', '[]', '[]', '{"type": "state", "config": {}, "mappings": null}', '{"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}', '{}', 0, NULL, '1', TRUE, FALSE, '2026-08-25 12:24:41.996755+00:00', '2026-08-25 13:06:28.268983+00:00', 0
WHERE NOT EXISTS (SELECT 1 FROM deep_agent_templates WHERE name = 'Advanced SQL Expert');

