ue, "long_term_memory": false}, "skills": [], "plugins": [], "skill_router_model": null, "disable_memory_middleware": false, "interrupt_before": null, "interrupt_after": null, "export_format": "standalone", "include_chat_ui": true, "include_docker": false, "tool_params": {"sql_agent_tool": {"database": "chinook"}}}', '[]', '[]', '{"type": "state", "config": {}, "mappings": null}', '{"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}', '{}', 0, NULL, '1.0.0', TRUE, FALSE, '2026-08-22 14:43:23.413863+00:00', '2026-08-23 11:47:22.619784+00:00', 1
