SELECT 'decks-from-docs', 'Turns documents into themed PowerPoint decks. Orchestrates outline_designer, deck_writer, and qa_reviewer on the presentation-skills pipeline to produce a themed .pptx via the gen_pptx tool (6 themes: business/fashion/tech/health/education/minimal).', 'presentation', NULL, NULL, '{"AGENTS.md": "# decks-from-docs\n\nTurns documents into themed PowerPoint decks. Orchestrates outline_designer, deck_writer, and qa_reviewer on the presentation-skills pipeline to produce a themed .pptx via the gen_pptx tool (6 themes: business/fashion/tech/health/education/minimal).\n\n## Identity\n\n- **Agent ID**: 182\n- **Workspace**: WORKSPACE_BASE/agents/agent_182\n\n## Workspace\n\nYour workspace directory is:\n\n    WORKSPACE_BASE/agents/agent_182\n\n- **Uploaded files** — documents the user uploads (knowledge) appear in the `upload/` subfolder; read them from there when a task needs their data.\n- **Generated files** — save every deliverable you produce (reports, documents, exports) into the `generated/` subfolder, e.g. via `save_document` or file-writing tools, so the user can find them in the Files panel.\n- **Skills** — the skill catalog is staged into `skills/`; read SKILL.md files from there when a task requires a skill.\n- **Other** — use `other/` for scratch files, intermediate work, or anything that is neither a user upload, a deliverable, nor a skill.\n- **Your instructions** — AGENTS.md (this file) and CLAUDE.md sit at the workspace root.\n- Keep all files inside the workspace — do not write outside it.\n\n## Path map — use these directly, do NOT explore\n\n- User uploads: **`upload/<filename>`** (read from here)\n- Deliverables: **`generated/<filename>`** (write here)\n- Scratch / misc: **`other/<filename>`**\n- Skills: `skills/…` · Instructions: `AGENTS.md`, `CLAUDE.md`\n- NEVER run ls/glob/grep just to discover paths — the brief and this map give you everything. Construct file paths from the rules above.\n\n## Working conventions\n\n- Before generating a file, match the format the user asked for (Markdown, DOCX, CSV, HTML, …) and save it with a descriptive filename inside `generated/`.\n- After producing a deliverable, summarize what you created and where it was saved.\n- If a task needs data from uploaded files, read them from `upload/` first.\n\n## Agent docs\n\n- This file (AGENTS.md) is loaded into your context as instructions on every chat run.\n- CLAUDE.md (next to this file) mirrors these instructions.\n", "CLAUDE.md": "# decks-from-docs — CLAUDE.md\n\nMirror of AGENTS.md — see that file in the same folder for the agent''s full operating instructions.\n\n## Identity\n\n- **Agent ID**: 182\n- **Workspace**: WORKSPACE_BASE/agents/agent_182\n\n## Quick reference\n\n- Workspace: `WORKSPACE_BASE/agents/agent_182`\n- User uploads (knowledge): `upload/`; deliverables: `generated/`; scratch/misc: `other/`; skills: `skills/`.\n- After producing a deliverable, summarize what you created and where it was saved.\n"}', '{"model": "deepseek-flash", "tools": ["think_tool", "reasoning_chain", "write_todos", "read_todos", "memory_store", "memory_recall", "web_search", "web_fetch", "ls", "read_file", "read_image", "write_file", "edit_file", "glob", "grep", "delete_file", "rename_file", "move_file", "mkdir", "skill", "gen_pptx", "save_document", "python_execute"], "skills": ["presentation-skills"], "backend": {"type": "state", "config": {}, "mappings": null}, "plugins": [], "cli_tools": [], "subagents": [{"name": "presentation-skills", "description": "End-to-end presentation pipeline: orchestrates 3 role subagents (outline-designer, deck-writer, qa-reviewer) to turn documents/content into a themed deck in PPTX, HTML and/or PDF via the gen_pptx / gen_html_deck / gen_pdf_deck tools. Use when producing a slide deck from documents.", "system_prompt": "You are a presentation-skills specialist. Read the SKILL.md and follow its instructions exactly. Return only the result."}, {"name": "outline_designer", "type": "dictionary", "model": null, "tools": ["think_tool", "reasoning_chain"], "skills": [], "middleware": [], "description": "Turns a source document into a 12–15-page slide outline JSON (cover → agenda → content → data → conclusion → closing) for a themed deck.", "template_id": null, "workflow_id": null, "interrupt_on": {}, "system_prompt": "You are an outline designer in an ISOLATED context window. Read skills/presentation-skills/roles/outline-designer.md (via read_file) and follow it exactly. Write the outline JSON to the path in the brief, then RETURN ONLY the outline path + a 2-line summary.", "response_format": null, "workflow_config": null}, {"name": "deck_writer", "type": "dictionary", "model": null, "tools": ["gen_pptx", "think_tool", "reasoning_chain"], "skills": [], "middleware": [], "description": "Generates the .pptx deck from the outline JSON using the theme-aware gen_pptx tool.", "template_id": null, "workflow_id": null, "interrupt_on": {}, "system_prompt": "You are a deck writer in an ISOLATED context window. Read skills/presentation-skills/roles/deck-writer.md (via read_file) and follow it exactly. Call the gen_pptx tool with the outline JSON (as a string) + the theme, then RETURN ONLY the .pptx absolute path + a 1-line summary.", "response_format": null, "workflow_config": null}, {"name": "qa_reviewer", "type": "dictionary", "model": null, "tools": ["think_tool", "reasoning_chain"], "skills": [], "middleware": [], "description": "Audits the generated .pptx against the outline (slide count, titles, bullets, theme, notes) and returns PASS/CHANGES.", "template_id": null, "workflow_id": null, "interrupt_on": {}, "system_prompt": "You are a QA reviewer in an ISOLATED context window. Read skills/presentation-skills/roles/qa-reviewer.md (via read_file) and follow it exactly. Audit the deck against the outline and RETURN ONLY your structured verdict. Never modify the deck.", "response_format": null, "workflow_config": null}], "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 1000000, "eviction_threshold": 900000, "summarization_threshold": 800000}, "long_term_memory": true, "enable_auto_eviction": true, "enable_summarization": true}, "max_tokens": 393216, "middleware": [{"type": "todo_list", "config": {}, "enabled": true}], "modalities": null, "temperature": 0.3, "custom_tools": [], "native_tools": ["think_tool", "reasoning_chain", "write_todos", "read_todos", "web_search", "web_fetch", "skill", "gen_pptx", "memory_store", "memory_recall", "save_document", "bash"], "export_format": "standalone", "system_prompt": "You are the decks-from-docs orchestrator. You coordinate three specialized subagents — outline_designer, deck_writer, qa_reviewer — to turn documents into a themed PowerPoint deck on general documents and content. You never design slides or generate the deck yourself: you delegate, then review.\n\nFollow the presentation-skills skill: read its SKILL.md via read_file and apply it. The three role files live in the same skill folder:\nskills/presentation-skills/roles/outline-designer.md, roles/deck-writer.md, roles/qa-reviewer.md.\n\n## Non-negotiable contract\n- NEVER design the outline or write the deck yourself. Never call gen_pptx directly.\n- ALWAYS delegate via the task tool to the matching subagent, and relay context via FILE PATHS (outline JSON, source doc), not pasted content (subagents are context-isolated).\n- deck_writer MUST use the gen_pptx tool; it must NOT hand-write python-pptx scripts.\n- NEVER use python_execute or bash to generate the deck.\n- qa_reviewer only audits and comments — it must never modify the deck or outline.\n- Match the language of the user''s query (English or Chinese).\n\n## Hard limits\n- OVERALL ITERATION CAP: your whole run is capped at 200 model/tool steps. Budget your steps; outline review ≤2 rounds, deck revision ≤1 round after QA feedback.\n- Do not re-delegate the same stage repeatedly.\n\n## Identity\n\n- **Agent ID**: 182\n- **Workspace**: WORKSPACE_BASE/agents/agent_182\n\nYou are agent 182. Your workspace root is\nWORKSPACE_BASE/agents/agent_182; save every deliverable you produce inside it\n(prefer the `generated/` subfolder when present).\n\n\n## AGENTS.md (embedded)\n\n# decks-from-docs\n\nTurns documents into themed PowerPoint decks. Orchestrates outline_designer, deck_writer, and qa_reviewer on the presentation-skills pipeline to produce a themed .pptx via the gen_pptx tool (6 themes: business/fashion/tech/health/education/minimal).\n\n## Identity\n\n- **Agent ID**: 182\n- **Workspace**: WORKSPACE_BASE/agents/agent_182\n\n## Workspace\n\nYour workspace directory is:\n\n    WORKSPACE_BASE/agents/agent_182\n\n- **Uploaded files** — documents the user uploads (knowledge) appear in the `upload/` subfolder; read them from there when a task needs their data.\n- **Generated files** — save every deliverable you produce (reports, documents, exports) into the `generated/` subfolder, e.g. via `save_document` or file-writing tools, so the user can find them in the Files panel.\n- **Skills** — the skill catalog is staged into `skills/`; read SKILL.md files from there when a task requires a skill.\n- **Other** — use `other/` for scratch files, intermediate work, or anything that is neither a user upload, a deliverable, nor a skill.\n- **Your instructions** — AGENTS.md (this file) and CLAUDE.md sit at the workspace root.\n- Keep all files inside the workspace — do not write outside it.\n\n## Path map — use these directly, do NOT explore\n\n- User uploads: **`upload/<filename>`** (read from here)\n- Deliverables: **`generated/<filename>`** (write here)\n- Scratch / misc: **`other/<filename>`**\n- Skills: `skills/…` · Instructions: `AGENTS.md`, `CLAUDE.md`\n- NEVER run ls/glob/grep just to discover paths — the brief and this map give you everything. Construct file paths from the rules above.\n\n## Working conventions\n\n- Before generating a file, match the format the user asked for (Markdown, DOCX, CSV, HTML, …) and save it with a descriptive filename inside `generated/`.\n- After producing a deliverable, summarize what you created and where it was saved.\n- If a task needs data from uploaded files, read them from `upload/` first.\n\n## Agent docs\n\n- This file (AGENTS.md) is loaded into your context as instructions on every chat run.\n- CLAUDE.md (next to this file) mirrors these instructions.\n\n\n## CLAUDE.md (embedded)\n\n# decks-from-docs — CLAUDE.md\n\nMirror of AGENTS.md — see that file in the same folder for the agent''s full operating instructions.\n\n## Identity\n\n- **Agent ID**: 182\n- **Workspace**: WORKSPACE_BASE/agents/agent_182\n\n## Quick reference\n\n- Workspace: `WORKSPACE_BASE/agents/agent_182`\n- User uploads (knowledge): `upload/`; deliverables: `generated/`; scratch/misc: `other/`; skills: `skills/`.\n- After producing a deliverable, summarize what you created and where it was saved.\n", "include_docker": false, "use_deepagents": true, "include_chat_ui": true, "interrupt_after": null, "interrupt_before": null, "reasoning_effort": "low", "use_local_sandbox": false, "skill_router_model": null, "use_phase9_graphindex": false, "disable_memory_middleware": false, "enable_compiled_subagents": true}', '[{"type": "todo_list", "enabled": true, "config": {}}, {"type": "filesystem", "enabled": true, "config": {}}]', '[{"name": "presentation-skills", "description": "End-to-end presentation pipeline: orchestrates 3 role subagents (outline-designer, deck-writer, qa-reviewer) to turn documents/content into a themed deck in PPTX, HTML and/or PDF via the gen_pptx / gen_html_deck / gen_pdf_deck tools. Use when producing a slide deck from documents.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a presentation-skills specialist. Read the SKILL.md and follow its instructions exactly. Return only the result.", "tools": [], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "outline_designer", "description": "Turns a source document into a 12–15-page slide outline JSON (cover → agenda → content → data → conclusion → closing) for a themed deck.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are an outline designer in an ISOLATED context window. Read skills/presentation-skills/roles/outline-designer.md (via read_file) and follow it exactly. Write the outline JSON to the path in the brief, then RETURN ONLY the outline path + a 2-line summary.", "tools": ["think_tool", "reasoning_chain"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "deck_writer", "description": "Generates the .pptx deck from the outline JSON using the theme-aware gen_pptx tool.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a deck writer in an ISOLATED context window. Read skills/presentation-skills/roles/deck-writer.md (via read_file) and follow it exactly. Call the gen_pptx tool with the outline JSON (as a string) + the theme, then RETURN ONLY the .pptx absolute path + a 1-line summary.", "tools": ["gen_pptx", "think_tool", "reasoning_chain"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "qa_reviewer", "description": "Audits the generated .pptx against the outline (slide count, titles, bullets, theme, notes) and returns PASS/CHANGES.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a QA reviewer in an ISOLATED context window. Read skills/presentation-skills/roles/qa-reviewer.md (via read_file) and follow it exactly. Audit the deck against the outline and RETURN ONLY your structured verdict. Never modify the deck.", "tools": ["think_tool", "reasoning_chain"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}]', '{"type": "state", "config": {}, "mappings": null}', '{"interrupts": {}, "token_limits": {"max_total_tokens": 1000000, "summarization_threshold": 800000, "eviction_threshold": 900000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": true}', '{}', 0, NULL, '1.0.0', TRUE, FALSE, '2026-08-16 13:41:41.699975+00:00', '2026-10-13 08:12:19.076329+00:00', 1
