/agent_3`\n- User uploads (knowledge): `upload/`; deliverables: `generated/`; scratch/misc: `other/`; skills: `skills/`.\n- After producing a deliverable, summarize what you created and where it was saved.\n", "tools": [], "native_tools": ["web_search", "think_tool", "reasoning_chain", "write_todos", "read_todos", "web_fetch", "rename_file", "move_file", "mkdir", "bash", "skill", "save_document", "memory_store", "memory_recall", "pg_list_tables", "pg_describe_table", "pg_query", "pg_list_agents", "pg_get_agent", "pg_list_projects", "sqlite_execute", "sqlite_load_csv", "python_execute", "save_analysis_result", "graphindex_search", "graphindex_load", "doc_index_list", "tavily_search"], "cli_tools": [], "custom_tools": [], "use_deepagents": true, "enable_compiled_subagents": true, "middleware": [{"type": "todo_list", "enabled": true, "config": {"auto_track": true}}, {"type": "filesystem", "enabled": true, "config": {"auto_eviction": true, "eviction_threshold_bytes": 1000000}}, {"type": "subagent", "enabled": true, "config": {"max_depth": 3, "max_concurrent": 5}}], "subagents": [{"name": "test_runner", "description": "Specialized in running and analyzing tests", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You run tests, analyze failures, and provide detailed test reports.", "tools": ["ls", "read_file", "write_file", "edit_file", "glob", "grep", "web_search"], "middleware": ["filesystem"], "interrupt_on": {}, "workflow_id": null, "workflow_config": null}], "backend": {"type": "composite", "config": {}, "mappings": {"/memory/": {"type": "vectordb", "config": {}}, "/filesystem/": {"type": "filesystem", "config": {}}, "/state/": {"type": "state", "config": {}}}}, "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 150000, "eviction_threshold": 100000, "summarization_threshold": 70000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}, "export_format": "standalone", "include_chat_ui": tru