"], "cli_tools": [], "custom_tools": [], "use_deepagents": true, "enable_compiled_subagents": true, "use_local_sandbox": true, "middleware": [{"type": "todo_list", "enabled": true, "config": {"auto_track": true}}, {"type": "filesystem", "enabled": true, "config": {"auto_eviction": true, "eviction_threshold_bytes": 1000000}}, {"type": "subagent", "enabled": true, "config": {"max_depth": 3, "max_concurrent": 5}}], "subagents": [{"name": "pdf-chat", "description": "Search and read project documents (PDF, MD, DOCX, PPT, TXT) using GraphIndex vectorless RAG. Use when the user asks about a document, report, or file, or wants to find content in the project knowledge base.", "system_prompt": "You are a pdf-chat specialist. Read the SKILL.md and follow its instructions exactly. Return only the result."}], "backend": {"type": "state", "config": {}, "mappings": null}, "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}, "skills": ["pdf-chat"], "skill_router_model": "minimax-m3", "interrupt_before": null, "interrupt_after": null, "export_format": "standalone", "include_chat_ui": true, "include_docker": false}', '[{"type": "todo_list", "enabled": true, "config": {"auto_track": true}}, {"type": "filesystem", "enabled": true, "config": {"auto_eviction": true, "eviction_threshold_bytes": 1000000}}, {"type": "subagent", "enabled": true, "config": {"max_depth": 3, "max_concurrent": 5}}]', '[{"name": "pdf-chat", "description": "Search and read project documents (PDF, MD, DOCX, PPT, TXT) using GraphIndex vectorless RAG. Use when the user asks about a document, report, or file, or wants to find content in the project knowledge base.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a pdf-chat specialist. Read the SKILL.md and follow its instructions exactly. Return only the res