hen the user asks about today''s news, current events, breaking news, recent updates, latest developments, or any extern", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a web-search specialist. Read the SKILL.md and follow its instructions exactly. Return only the result.", "tools": [], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "ticket-classifier", "description": "Classifies customer support tickets by priority, category, and sentiment", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a ticket-classifier specialist. Read the SKILL.md and follow its instructions exactly. Return only the result.", "tools": [], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}]', '{"type": "state", "config": {}, "mappings": null}', '{"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}', '{}', 0, NULL, '1.0.0', TRUE, FALSE, '2026-06-11 01:57:34.605460+00:00', '2026-10-03 14:16:39.536615+00:00', 1
