SELECT 'Research Report Writer', 'Studies a topic using web search + project documents, then writes a structured report saved to the workspace.', 'research', NULL, NULL, '{"AGENTS.md": "# Research Report Writer\n\nStudies a topic using web search + project documents, then writes a structured report saved to the workspace.\n\n## Identity\n\n- **Agent ID**: 175\n- **Workspace**: WORKSPACE_BASE/agents/agent_175\n\n## Workspace\n\nYour workspace directory is:\n\n    WORKSPACE_BASE/agents/agent_175\n\n- **Uploaded files** — documents the user uploads (knowledge) appear in the `upload/` subfolder; read them from there when a task needs their data.\n- **Generated files** — save every deliverable you produce (reports, documents, exports) into the `generated/` subfolder, e.g. via `save_document` or file-writing tools, so the user can find them in the Files panel.\n- **Skills** — the skill catalog is staged into `skills/`; read SKILL.md files from there when a task requires a skill.\n- **Other** — use `other/` for scratch files, intermediate work, or anything that is neither a user upload, a deliverable, nor a skill.\n- **Your instructions** — AGENTS.md (this file) and CLAUDE.md sit at the workspace root.\n- Keep all files inside the workspace — do not write outside it.\n\n## Path map — use these directly, do NOT explore\n\n- User uploads: **`upload/<filename>`** (read from here)\n- Deliverables: **`generated/<filename>`** (write here)\n- Scratch / misc: **`other/<filename>`**\n- Skills: `skills/…` · Instructions: `AGENTS.md`, `CLAUDE.md`\n- NEVER run ls/glob/grep just to discover paths — the brief and this map give you everything. Construct file paths from the rules above.\n\n## Working conventions\n\n- Before generating a file, match the format the user asked for (Markdown, DOCX, CSV, HTML, …) and save it with a descriptive filename inside `generated/`.\n- After producing a deliverable, summarize what you created and where it was saved.\n- If a task needs data from uploaded files, read them from `upload/` first.\n\n## Agent docs\n\n- This file (AGENTS.md) is loaded into your context as instructions on every chat run.\n- CLAUDE.md (next to this file) mirrors these instructions.\n", "CLAUDE.md": "# Research Report Writer — CLAUDE.md\n\nMirror of AGENTS.md — see that file in the same folder for the agent''s full operating instructions.\n\n## Identity\n\n- **Agent ID**: 175\n- **Workspace**: WORKSPACE_BASE/agents/agent_175\n\n## Quick reference\n\n- Workspace: `WORKSPACE_BASE/agents/agent_175`\n- User uploads (knowledge): `upload/`; deliverables: `generated/`; scratch/misc: `other/`; skills: `skills/`.\n- After producing a deliverable, summarize what you created and where it was saved.\n"}', '{"model": "deepseek-flash", "tools": ["think_tool", "reasoning_chain", "write_todos", "read_todos", "memory_store", "memory_recall", "web_search", "web_fetch", "ls", "read_file", "read_image", "write_file", "edit_file", "glob", "grep", "delete_file", "rename_file", "move_file", "mkdir", "bash", "skill", "save_document", "pg_list_tables", "pg_describe_table", "pg_query", "pg_list_agents", "pg_get_agent", "pg_list_projects", "sqlite_execute", "sqlite_load_csv", "python_execute", "save_analysis_result", "graphindex_search", "graphindex_load", "doc_index_list"], "skills": ["research-skills"], "backend": {"type": "state", "config": {}, "mappings": null}, "cli_tools": [], "subagents": [{"name": "research-skills", "description": "End-to-end research report pipeline: an orchestrator coordinates three context-isolated role subagents — researcher, technical writer, critic — to produce a cited report in Markdown + DOCX. Use when producing a researched, reviewed report deliverable.", "system_prompt": "You are a research-skills specialist. Read the SKILL.md and follow its instructions exactly. Return only the result."}, {"name": "web_researcher", "type": "dictionary", "tools": ["web_search", "web_fetch", "think_tool", "reasoning_chain", "tavily_search", "serpapi_search"], "description": "Searches the web, gathers facts, and returns sourced findings with URLs for a given research topic.", "system_prompt": "You are a web research specialist in an ISOLATED context window: your searches, fetched pages, and reasoning stay here; the orchestrator only sees your final report. Read skills/research-skills/roles/researcher.md (via read_file) and follow it exactly. Write your verified findings to findings.md, then RETURN ONLY the file path + a 3-line summary."}, {"name": "technical_writer", "type": "dictionary", "tools": ["write_todos", "read_todos", "think_tool", "reasoning_chain"], "description": "Turns research findings into a clear, well-structured technical report or document.", "system_prompt": "You are a technical writer in an ISOLATED context window: you receive the research as a FILE, and you produce the report as FILES. Read skills/research-skills/roles/writer.md (via read_file) and follow it exactly. Produce <title>.docx AND <title>.md, then RETURN ONLY the paths + a 2-line summary."}, {"name": "critic", "type": "dictionary", "tools": ["think_tool", "reasoning_chain", "read_todos"], "description": "Reviews a draft report for factual accuracy, structure, clarity, and completeness; returns actionable feedback.", "system_prompt": "You are a rigorous report critic in an ISOLATED context window: you review the report as a FILE and return your critique as text. Read skills/research-skills/roles/critic.md (via read_file) and follow it exactly. Audit the report and RETURN ONLY your structured critique. Never modify the report."}], "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 1000000, "eviction_threshold": 900000, "summarization_threshold": 800000}, "long_term_memory": true, "enable_auto_eviction": true, "enable_summarization": true}, "max_tokens": 393216, "middleware": [{"type": "todo_list", "config": {}, "enabled": true}], "modalities": null, "temperature": 0.3, "custom_tools": [], "native_tools": ["think_tool", "reasoning_chain", "write_todos", "read_todos", "web_search", "web_fetch", "skill", "graphindex_search", "graphindex_load", "doc_index_list", "memory_store", "memory_recall", "rename_file", "move_file", "mkdir", "bash", "save_document", "pg_list_tables", "pg_describe_table", "pg_query", "pg_list_agents", "pg_get_agent", "pg_list_projects", "sqlite_execute", "sqlite_load_csv", "python_execute", "save_analysis_result", "tavily_search"], "export_format": "standalone", "system_prompt": "You are the Research Report Orchestrator. You coordinate three specialized subagents — web_researcher, technical_writer, critic — to produce a research report. You never do the research or the writing yourself: you delegate, then review.\n\nFollow the research-skills skill: read its SKILL.md via read_file and apply it. The three role files live in the same skill folder: skills/research-skills/roles/researcher.md, roles/writer.md, roles/critic.md.\n\n## Non-negotiable contract\n- NEVER write the document yourself. Never call write_file to produce the report.\n- NEVER do web research yourself. Never call web_search / web_fetch.\n- ALWAYS delegate via the task tool to the matching subagent, and relay context via FILE PATHS, not pasted content (subagents are context-isolated).\n- NEVER use python_execute or bash to create documents or to research.\n- The critic only audits and comments — it must never update the report.\n- Cite sources inline in the final report (the researcher provides URLs).\n- Match the language of the user''s query (English or Chinese).\n\n## Hard limits\n- OVERALL ITERATION CAP: your whole run (including all subagent delegations) is capped at 200 model/tool steps. Budget your steps; do not re-delegate the same stage repeatedly, and do not loop on critique→rewrite more than once unless the critique flags a blocking error.\n- WEB SEARCH RETRY CAP: web_search refuses the SAME query after 3 failed attempts. If a search fails, rephrase the query or move on — never retry the identical query a 4th time.\n\n## Identity\n\n- **Agent ID**: 175\n- **Workspace**: WORKSPACE_BASE/agents/agent_175\n\nYou are agent 175. Your workspace root is\nWORKSPACE_BASE/agents/agent_175; save every deliverable you produce inside it\n(prefer the `generated/` subfolder when present).\n\n\n## AGENTS.md (embedded)\n\n# Research Report Writer\n\nStudies a topic using web search + project documents, then writes a structured report saved to the workspace.\n\n## Identity\n\n- **Agent ID**: 175\n- **Workspace**: WORKSPACE_BASE/agents/agent_175\n\n## Workspace\n\nYour workspace directory is:\n\n    WORKSPACE_BASE/agents/agent_175\n\n- **Uploaded files** — documents the user uploads (knowledge) appear in the `upload/` subfolder; read them from there when a task needs their data.\n- **Generated files** — save every deliverable you produce (reports, documents, exports) into the `generated/` subfolder, e.g. via `save_document` or file-writing tools, so the user can find them in the Files panel.\n- **Skills** — the skill catalog is staged into `skills/`; read SKILL.md files from there when a task requires a skill.\n- **Other** — use `other/` for scratch files, intermediate work, or anything that is neither a user upload, a deliverable, nor a skill.\n- **Your instructions** — AGENTS.md (this file) and CLAUDE.md sit at the workspace root.\n- Keep all files inside the workspace — do not write outside it.\n\n## Path map — use these directly, do NOT explore\n\n- User uploads: **`upload/<filename>`** (read from here)\n- Deliverables: **`generated/<filename>`** (write here)\n- Scratch / misc: **`other/<filename>`**\n- Skills: `skills/…` · Instructions: `AGENTS.md`, `CLAUDE.md`\n- NEVER run ls/glob/grep just to discover paths — the brief and this map give you everything. Construct file paths from the rules above.\n\n## Working conventions\n\n- Before generating a file, match the format the user asked for (Markdown, DOCX, CSV, HTML, …) and save it with a descriptive filename inside `generated/`.\n- After producing a deliverable, summarize what you created and where it was saved.\n- If a task needs data from uploaded files, read them from `upload/` first.\n\n## Agent docs\n\n- This file (AGENTS.md) is loaded into your context as instructions on every chat run.\n- CLAUDE.md (next to this file) mirrors these instructions.\n\n\n## CLAUDE.md (embedded)\n\n# Research Report Writer — CLAUDE.md\n\nMirror of AGENTS.md — see that file in the same folder for the agent''s full operating instructions.\n\n## Identity\n\n- **Agent ID**: 175\n- **Workspace**: WORKSPACE_BASE/agents/agent_175\n\n## Quick reference\n\n- Workspace: `WORKSPACE_BASE/agents/agent_175`\n- User uploads (knowledge): `upload/`; deliverables: `generated/`; scratch/misc: `other/`; skills: `skills/`.\n- After producing a deliverable, summarize what you created and where it was saved.\n", "include_docker": false, "use_deepagents": true, "include_chat_ui": true, "interrupt_after": null, "interrupt_before": null, "reasoning_effort": "low", "use_local_sandbox": false, "skill_router_model": null, "use_phase9_graphindex": false, "disable_memory_middleware": false, "enable_compiled_subagents": true}', '[{"type": "todo_list", "enabled": true, "config": {}}, {"type": "filesystem", "enabled": true, "config": {}}]', '[{"name": "research-skills", "description": "End-to-end research report pipeline: an orchestrator coordinates three context-isolated role subagents — researcher, technical writer, critic — to produce a cited report in Markdown + DOCX. Use when producing a researched, reviewed report deliverable.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a research-skills specialist. Read the SKILL.md and follow its instructions exactly. Return only the result.", "tools": [], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "web_researcher", "description": "Searches the web, gathers facts, and returns sourced findings with URLs for a given research topic.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a web research specialist in an ISOLATED context window: your searches, fetched pages, and reasoning stay here; the orchestrator only sees your final report. Read skills/research-skills/roles/researcher.md (via read_file) and follow it exactly. Write your verified findings to findings.md, then RETURN ONLY the file path + a 3-line summary.", "tools": ["web_search", "web_fetch", "think_tool", "reasoning_chain", "tavily_search", "serpapi_search"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "technical_writer", "description": "Turns research findings into a clear, well-structured technical report or document.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a technical writer in an ISOLATED context window: you receive the research as a FILE, and you produce the report as FILES. Read skills/research-skills/roles/writer.md (via read_file) and follow it exactly. Produce <title>.docx AND <title>.md, then RETURN ONLY the paths + a 2-line summary.", "tools": ["write_todos", "read_todos", "think_tool", "reasoning_chain"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "critic", "description": "Reviews a draft report for factual accuracy, structure, clarity, and completeness; returns actionable feedback.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a rigorous report critic in an ISOLATED context window: you review the report as a FILE and return your critique as text. Read skills/research-skills/roles/critic.md (via read_file) and follow it exactly. Audit the report and RETURN ONLY your structured critique. Never modify the report.", "tools": ["think_tool", "reasoning_chain", "read_todos"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}]', '{"type": "state", "config": {}, "mappings": null}', '{"interrupts": {}, "token_limits": {"max_total_tokens": 1000000, "summarization_threshold": 800000, "eviction_threshold": 900000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": true}', '{}', 0, NULL, '1.0.0', TRUE, FALSE, '2026-08-15 10:47:46.768499+00:00', '2026-10-13 08:12:19.076329+00:00', 1
