.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a skill-generator specialist. Read the SKILL.md and follow its instructions exactly. Return only the result.", "tools": [], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "text-summarizer", "description": "Summarizes long text into concise bullet points.", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a text-summarizer specialist. Read the SKILL.md and follow its instructions exactly. Return only the result.", "tools": [], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "web-search", "description": "Search the web for the latest news, current events, and recent information. Use when the user asks about today''s news, current events, breaking news, recent updates, latest developments, or any extern", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a web-search specialist. Read the SKILL.md and follow its instructions exactly. Return only the result.", "tools": [], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "ticket-classifier", "description": "Classifies customer support tickets by priority, category, and sentiment", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "You are a ticket-classifier specialist. Read the SKILL.md and follow its instructions exactly. Return only the result.", "tools": [], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}, {"name": "pdf-chat-assistant", "description": "Search and read project documents (PDF, MD, DOCX, PPT, TXT). Uses GraphIndex vectorless RAG.", "type": "dictionary", "template_id": null, "model": null, "system_prom